package com.example.demo.service.impl;
import com.example.demo.dto.HolidayDTO;import com.example.demo.mapper.HolidayMapper;import com.example.demo.model.Holiday;import com.example.demo.repository.HolidayRepository;import com.example.demo.service.params.request.schedule.CreateHolidayRequest;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import java.time.LocalDate;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class HolidayServiceImplTest{@Mock HolidayMapper mapper;@Mock HolidayRepository repo;HolidayServiceImpl service;@BeforeEach void setup(){service=new HolidayServiceImpl(mapper,repo);}@Test void createMapsAndSaves(){var req=new CreateHolidayRequest(LocalDate.now(),"Praznik");var entity=new Holiday();var dto=new HolidayDTO();when(mapper.toEntity(req)).thenReturn(entity);when(repo.save(entity)).thenReturn(entity);when(mapper.toDTO(entity)).thenReturn(dto);assertSame(dto,service.create(req));}@Test void closedAndDeleteDelegate(){LocalDate date=LocalDate.now();when(repo.existsByDate(date)).thenReturn(true);assertTrue(service.isGymClosedOn(date));service.delete(9);verify(repo).deleteById(9);}}
